REPO = ROOT / 'zoo'
PINS = {'CHANGELOG.md': 'ec4485c0bb9660de', 'VERSION': '2ee8d789ba375503', 'zoo_keeper/core/dressing.py': '0bf1d7dda57edf14', 'zoo_keeper/recipes/dress_cover.py': '138b4d808fa204a0'}
EDITS = {'CHANGELOG.md': [('lines 1-1', '## [1.153.0] - a stain where water runs down a wall\n', "## [1.154.0] - grime at a wall's base\n\nThe factory's roadmap 324. Patina (>= 0.40.0) orders a `stain_base` along each span of a ground storey's wall.\n\n### Added\n- **`stain_base`** (`dressing.grime_grid`, `recipes/dress_cover.py`): grime at a wall's base -- rain splashes back and\n  damp rises, so a wall darkens from the ground up. A grid `STAIN_PROUD` off the wall along a whole span, a column\n  every `GRIME_COL` (0.3 m), darkest at the ground (`GRIME_DARK` 0.35) and fading linearly to 1.0 at each column's\n  own top, which `GRIME_TOP` lifts to 55-100 % of the band and smooths with its neighbours so the edge wanders; it\n  fades out over its last `GRIME_END` (0.2 m), where Patina ends the span at a corner or an opening. A stain in every\n  other way (`STAIN_COVERS`): the wall's skin renamed `_stain`, which Level Factory (>= 0.271.0) draws in the\n  building's one stain mesh, so on a building that already had stains it costs no draw.\n\n### Retracted, kept (the factory's `docs/findings/slice_look/`)\n- **Slice 18:** every band faced INTO its building. `stain_grid`'s rows run down the wall and `grime_grid`'s up, and\n  the same quad order then winds the other way; the overlay culls back faces, so the bands were submitted and never\n  drawn (the GLB's normals read -x on the bank's +x face). Both grids are now tested to face out.\n- **Slice 18b:** `GRIME_DARK` 0.6 with a 1.6-power fade read as a 4 % darkening a few pixels tall at the bank's\n  foot from the street. 0.35 and a linear fade (slice 20): about -11 there under the inspection light, and at\n  evening a darker footing along the wall.\n\nTests: tests/test_stain_base.py.\n\n## [1.153.0] - a stain where water runs down a wall\n")], 'VERSION': [('lines 1-1', '1.153.0', '1.154.0')], 'zoo_keeper/core/dressing.py': [('lines 125-125', 'STAIN_COVERS = ("stain_streak",)\n', 'STAIN_COVERS = ("stain_streak", "stain_base")\n'), ('lines 134-135', 'STAIN_ROWS = 6\n\n', "STAIN_ROWS = 6\n#: GRIME AT A WALL'S BASE (1.154.0): rain splashes back off the ground and damp rises, so a wall darkens from the\n#: ground up and its top edge wanders. A `stain_base` is a grid laid `STAIN_PROUD` off the wall along a whole\n#: span of it, darkest at the ground (`GRIME_DARK`) and fading to 1.0 at its top, which each column lifts to its\n#: own share of the band (`GRIME_TOP`, smoothed with its neighbours so the edge wanders rather than saws); it\n#: fades out only over its last `GRIME_END` metres, where Patina ends the span at a corner or an opening. It is a\n#: stain in every other way: the wall's skin, `STAIN_SUFFIX`, drawn by Level Factory's overlay in the building's\n#: one stain mesh.\n#: 0.6 with a 1.6-power fade was measured faint (the factory's slice 18b): a 4 % darkening a few pixels tall at the\n#: bank's foot from the street, and barely there up close; darker, and a linear fade, so it reads its height\nGRIME_DARK = 0.35\n#: a column every this many metres along the span\nGRIME_COL = 0.3\nGRIME_ROWS = 4\nGRIME_TOP = (0.55, 1.0)\nGRIME_END = 0.2\n\n"), ('lines 210-211', '            faces.append((a, a + 1, a + cols + 2, a + cols + 1))\n    return verts, faces, shade\n', '            faces.append((a, a + 1, a + cols + 2, a + cols + 1))\n    return verts, faces, shade\n\n\ndef grime_grid(width: float, height: float, seed: int):\n    """``(verts, faces, shade)`` of a wall base\'s grime in cover-local space: x along the span, y out of the wall\n    at `STAIN_PROUD`, z up from the ground (0) to each column\'s own top, at most ``height``; ``faces`` index\n    quads, ``shade`` the `Wear` value a vertex carries -- darkest at the ground, 1.0 on the top row and at both\n    ends. Pure and deterministic for a seed."""\n    import math\n    import random\n    r = random.Random(int(seed))\n    width, height = float(width), float(height)\n    cols, rows = max(2, int(math.ceil(width / GRIME_COL - 1e-9))), GRIME_ROWS\n    raw = [r.uniform(*GRIME_TOP) for _ in range(cols + 1)]\n    tops = [(raw[max(i - 1, 0)] + 2.0 * raw[i] + raw[min(i + 1, cols)]) / 4.0 for i in range(cols + 1)]\n    col_k = [0.7 + 0.3 * r.random() for _ in range(cols + 1)]\n    verts, shade = [], []\n    for j in range(rows + 1):\n        t = j / rows                                    # 0 at the ground, 1 at the column\'s top\n        for i in range(cols + 1):\n            x = -width / 2.0 + width * i / cols\n            e = min(1.0, min(x + width / 2.0, width / 2.0 - x) / GRIME_END)\n            end = e * e * (3.0 - 2.0 * e)\n            depth = (1.0 - GRIME_DARK) * (1.0 - t) * end * col_k[i]\n            verts.append((x, STAIN_PROUD, t * height * tops[i]))\n            shade.append(round(1.0 - depth, 4))\n    faces = []\n    for j in range(rows):\n        for i in range(cols):\n            a = j * (cols + 1) + i\n            # wound the other way from `stain_grid`\'s: its rows run DOWN the wall and these run up, so the same\n            # order would face the wall (slice 18 built every band facing into its building, culled unseen)\n            faces.append((a, a + cols + 1, a + cols + 2, a + 1))\n    return verts, faces, shade\n')], 'zoo_keeper/recipes/dress_cover.py': [('lines 131-133', '    elif cover == "stain_streak":\n        # where water runs down a wall (1.153.0); `size2` is [width, length]. The grid\'s own `Wear` colour is the\n        # stain, so it is finished without `wear_colors`, which would write over it.\n', '    elif cover in ("stain_streak", "stain_base"):\n        # where water runs down a wall (1.153.0), `size2` [width, length], and grime at its base (1.154.0), `size2`\n        # [span, height]. The grid\'s own `Wear` colour is the stain, so it is finished without `wear_colors`,\n        # which would write over it.\n'), ('lines 135-137', '        from ..core.dressing import STAIN_SUFFIX, stain_grid\n        width, length = (order.get("size2") or [0.8, 1.2])[:2]\n        verts, faces, shade = stain_grid(width, length, order.get("seed_offset", 0))\n', '        from ..core.dressing import STAIN_SUFFIX, grime_grid, stain_grid\n        if cover == "stain_base":\n            span, height = (order.get("size2") or [2.0, 0.6])[:2]\n            verts, faces, shade = grime_grid(span, height, order.get("seed_offset", 0))\n        else:\n            width, length = (order.get("size2") or [0.8, 1.2])[:2]\n            verts, faces, shade = stain_grid(width, length, order.get("seed_offset", 0))\n')]}
WHOLE = {}
NEW_FILES = {'tests/test_stain_base.py': '"""Grime at a wall\'s base (1.154.0, the factory\'s roadmap 324).\n\nPatina (>= 0.40.0) orders a `stain_base` along each span of a ground storey\'s wall between its corners and openings,\nnaming the wall\'s kind. Zoo lays a grid `STAIN_PROUD` off the wall, darkest at the ground and fading up to a top edge\nthat wanders, in the wall\'s own skin renamed with `STAIN_SUFFIX` -- a stain in every other way, so Level Factory\'s\noverlay (>= 0.271.0) draws it in the building\'s one stain mesh.\n"""\nimport pytest\n\nfrom zoo_keeper import TOOL_VERSION\nfrom zoo_keeper.core import genome\nfrom zoo_keeper.core import dressing as D\n\nSPACE = "spec/Blender Z-up raw coords"\n\n\ndef test_grime_is_darkest_at_the_ground_and_fades_up_and_out():\n    """FAILS ON 1.153.0: no grime."""\n    verts, faces, shade = D.grime_grid(6.0, 0.6, 11)\n    cols = len({round(v[0], 6) for v in verts}) - 1\n    rows = D.GRIME_ROWS\n    assert cols == 20 and len(verts) == (cols + 1) * (rows + 1) and len(faces) == cols * rows\n    ground, top = shade[: cols + 1], shade[rows * (cols + 1):]\n    # the ground row carries the darkest, never past GRIME_DARK; the top row is the wall exactly\n    assert min(ground) >= D.GRIME_DARK - 1e-9 and min(ground) < 0.75\n    assert all(s == 1.0 for s in top)\n    # both ends are the wall exactly: a span ends at a corner or an opening\n    for j in range(rows + 1):\n        assert shade[j * (cols + 1)] == 1.0 and shade[j * (cols + 1) + cols] == 1.0\n    # darkness falls going up every column\n    for i in range(1, cols):\n        col = [shade[j * (cols + 1) + i] for j in range(rows + 1)]\n        assert col == sorted(col)\n\n\ndef test_its_top_edge_wanders_inside_the_band_and_its_foot_is_on_the_ground():\n    verts, _faces, _shade = D.grime_grid(6.0, 0.6, 11)\n    cols = 20\n    foot = [v[2] for v in verts[: cols + 1]]\n    tops = [v[2] for v in verts[D.GRIME_ROWS * (cols + 1):]]\n    assert all(z == 0.0 for z in foot)\n    assert all(0.6 * D.GRIME_TOP[0] - 1e-9 <= z <= 0.6 + 1e-9 for z in tops)\n    assert max(tops) - min(tops) > 0.05\n    assert all(abs(v[1] - D.STAIN_PROUD) < 1e-12 for v in verts)\n\n\ndef test_deterministic_for_a_seed():\n    assert D.grime_grid(4.0, 0.5, 3) == D.grime_grid(4.0, 0.5, 3)\n    assert D.grime_grid(4.0, 0.5, 3) != D.grime_grid(4.0, 0.5, 4)\n\n\ndef test_it_is_a_stain_and_wears_the_walls_kind():\n    assert "stain_base" in D.STAIN_COVERS\n    order = {"cover": "stain_base", "pos": [0.0, 11.0, 0.0], "normal": [0.0, 1.0, 0.0], "size": 6.0,\n             "size2": [6.0, 0.6], "collision": "none", "seed_offset": 11, "wall_material": "brick"}\n    plan = D.dress_plan(order, genome.load_species("dress_cover"), "delco_1997", SPACE, TOOL_VERSION)\n    assert plan["material"] == "brick"\n    assert plan["order"]["size2"] == [6.0, 0.6]\n\n\ndef test_bpy_the_grime_is_the_walls_skin_renamed_with_its_colours(tmp_path):\n    pytest.importorskip("bpy")\n    import bpy\n    from zoo_keeper.bpylayer import build as B\n    order = {"cover": "stain_base", "pos": [0.0, 11.0, 0.0], "normal": [0.0, 1.0, 0.0], "size": 6.0,\n             "size2": [6.0, 0.6], "collision": "none", "seed_offset": 11, "wall_material": "brick"}\n    manifest = {"schema": "patina-dressing/1", "building_id": "t_bank", "space": SPACE, "orders": [order]}\n    B.build_dressing(manifest, str(tmp_path), theme="delco_1997", options={"save_blend": False})\n    objs = [o for o in bpy.data.objects if o.type == "MESH"]\n    assert objs\n    me = objs[0].data\n    assert any(m.name.endswith(D.STAIN_SUFFIX) for m in me.materials), [m.name for m in me.materials]\n    vals = [d.color[0] for d in me.color_attributes["Wear"].data]\n    assert min(vals) < 0.8 and max(vals) == pytest.approx(1.0)\n\n\ndef _face_normals(verts, faces):\n    out = []\n    for f in faces:\n        a, b, c = (verts[k] for k in f[:3])\n        e1 = [b[i] - a[i] for i in range(3)]\n        e2 = [c[i] - a[i] for i in range(3)]\n        out.append((e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0]))\n    return out\n\n\ndef test_every_face_of_both_grids_faces_out_of_the_wall():\n    """FAILS ON slice 18\'s grime_grid: its rows run up where a streak\'s run down, the same winding faced it into the\n    wall, and the overlay\'s back-face culling drew none of it. Cover-local +y is out of the wall, for both."""\n    for verts, faces, _shade in (D.grime_grid(6.0, 0.6, 11), D.stain_grid(0.9, 1.4, 7)):\n        assert all(n[1] > 0 for n in _face_normals(verts, faces))\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
